+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/** Immutable filter shared by the backend's page and count queries. */
+public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+    public static final CustomerFilter EMPTY = from("", Set.of());
+
+    public CustomerFilter {
+        nameTerms = List.copyOf(nameTerms);
+        statuses = Set.copyOf(statuses);
+    }
+
+    public static CustomerFilter from(String name, Set<CustomerStatus> statuses) {
+        List<String> terms = WHITESPACE.splitAsStream(normalize(name))
+                .filter(term -> !term.isEmpty()).toList();
+        return new CustomerFilter(terms, statuses);
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return nameTerms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private static String normalize(String value) {
+        return MARKS.matcher(Normalizer.normalize(value, Normalizer.Form.NFD))
+                .replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
